// 1. Grab the incoming data from the Webhook's 'body' folder
const lead = $input.first().json.body;

// 2. Clean the email (remove accidental spaces and make it lowercase)
const cleanEmail = (lead.email || "").trim().toLowerCase();

// 3. Extract the domain (everything after the '@' symbol)
const domain = cleanEmail.split('@')[1] || "";

// 4. List of free personal email providers we should NOT scrape
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
const isBusinessEmail = domain !== "" && !freeProviders.includes(domain);

// 5. Output clean, structured data for the rest of our pipeline
return [
  {
    json: {
      name: (lead.name || "Unknown").trim(),
      email: cleanEmail,
      company: (lead.company || "Unknown").trim(),
      message: (lead.message || "").trim(),
      domain: domain,
      is_business_email: isBusinessEmail,
      website_url: isBusinessEmail ? `https://${domain}` : null,
      received_at: new Date().toISOString()
    }
  }
];

