// 1. Grab the raw HTML returned by the HTTP Request node
const responseData = $input.first().json;
const rawHtml = responseData.data || "";

// 2. Strip out invisible code (<script>, <style>, comments, and HTML tags)
let cleanText = rawHtml
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ');

// 3. Remove extra blank spaces and line breaks
cleanText = cleanText.replace(/\s+/g, ' ').trim();

// 4. Keep only the first 1,500 characters
const companyContext = cleanText.substring(0, 1500);

// 5. Grab the clean lead details directly from our first 'Code' node
const originalLead = $('Code in JavaScript - Clean up codes, extracts Json data').first().json;

// 6. Grab the Airtable row ID from 'Create a record'
const airtableRecord = $('Database for incoming Leads - Create a record').first().json;

return [
  {
    json: {
      airtable_id: airtableRecord.id,
      name: originalLead.name,
      email: originalLead.email,
      company: originalLead.company,
      message: originalLead.message,
      website_url: originalLead.website_url,
      company_summary: companyContext || "Website could not be read or had no text."
    }
  }
];

// ============================================================================
// BRANCH-SAFE AI JSON PARSER & VALIDATOR (FIXED KEY MAPPING)
// ============================================================================

// Grab output from the immediate preceding AI Chain / Agent node
const sourceData = $input.first().json || {};

const rawOutput = sourceData.text 
               || sourceData.output 
               || sourceData.message?.content 
               || sourceData.response 
               || "";

// Safely grab the Airtable Record ID from the upstream Airtable Create node
let airtableRecordId = null;
try {
  airtableRecordId = $('Create a record').first().json.id;
} catch (e) {
  airtableRecordId = sourceData.id || null;
}

try {
  // Strip any accidental markdown code fences (```json ... ```)
  const cleanJsonString = String(rawOutput)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const parsed = JSON.parse(cleanJsonString);

  // Extract the summary whether the AI named it 'ai_summary' or 'company_summary'
  const summaryText = parsed.ai_summary 
                   || parsed.company_summary 
                   || "No company website scraped (Personal/Free Email).";

  return [
    {
      json: {
        airtable_record_id: airtableRecordId,
        qualification_score: Number(parsed.qualification_score ?? parsed.score ?? 0),
        buyer_intent: parsed.buyer_intent || "Low",
        ai_summary: summaryText,
        company_summary: summaryText,
        pain_points: Array.isArray(parsed.pain_points) 
          ? parsed.pain_points.join(", ") 
          : (parsed.pain_points || "None identified"),
        draft_reply: parsed.draft_reply || "No reply drafted (Cold/Unqualified Lead).",
        ai_status: "AI Processed"
      }
    }
  ];
} catch (error) {
  // Fallback if the LLM returned broken JSON
  return [
    {
      json: {
        airtable_record_id: airtableRecordId,
        qualification_score: 0,
        buyer_intent: "Error",
        ai_summary: "AI JSON Parsing Failed",
        company_summary: "AI JSON Parsing Failed",
        pain_points: "Manual review required",
        draft_reply: "",
        ai_status: "Manual Review Required",
        error_details: error.message,
        raw_debug: String(rawOutput)
      }
    }
  ];
}
